  topic: 'CLUSTER_OPERATIONS',
  content: {
    text: `[${complexity}:${taskType}] ${reasoning}`,
    data: {
      complexity,
      taskType,
      taskFocus,
      operations: [
        { action: 'load_config', config },
        { action: 'publish', topic: 'ISSUE_OPENED', content: { text: executionText }, metadata: { _republished: true } }
      ]
    }
  }
};

